<script setup lang="ts">
import {ref,reactive} from 'vue';import {roleLabels,roles,type SessionUser} from '@briochett/contracts';import {api,errorMessage} from '../api';import {useList} from '../composables';import PageHeader from '../components/PageHeader.vue';import Pagination from '../components/Pagination.vue';import AppModal from '../components/AppModal.vue';
const {data,page,busy,error,load}=useList<SessionUser>(()=>'/users'),open=ref(false),selected=ref<SessionUser|null>(null),saving=ref(false),formError=ref(''),reset=ref(false),password=ref(''),form=reactive({name:'',email:'',username:'',role:'vendedor',password:'',active:true});
function edit(u:SessionUser|null){selected.value=u;Object.assign(form,u?{name:u.name,email:u.email,username:u.username,role:u.role,password:'',active:u.active}:{name:'',email:'',username:'',role:'vendedor',password:'',active:true});formError.value='';reset.value=false;open.value=true;}
async function save(){saving.value=true;formError.value='';try{await api(selected.value?'/users/'+selected.value.id:'/users',{method:selected.value?'PATCH':'POST',body:selected.value?{name:form.name,email:form.email,role:form.role,active:form.active}:form});open.value=false;form.password='';load();}catch(e){formError.value=errorMessage(e);}finally{saving.value=false;}}
async function resetPassword(){saving.value=true;formError.value='';try{await api('/users/'+selected.value!.id+'/password',{method:'POST',body:{password:password.value}});password.value='';open.value=false;load();}catch(e){formError.value=errorMessage(e);}finally{saving.value=false;}}
</script>
<template><PageHeader title="Usuarios" description="Cuentas, roles y acceso al sistema" /><div class="toolbar"><button @click="edit(null)">+ Nuevo usuario</button></div><p v-if="error" class="notice error" role="alert">{{error}}</p><section class="card"><h2>Equipo de trabajo</h2><div class="table-wrap"><table v-responsive-table><thead><tr><th>Nombre</th><th>Usuario</th><th>Rol</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="u in data.items" :key="u.id"><td class="strong">{{u.name}}</td><td>{{u.username}}</td><td>{{roleLabels[u.role]}}</td><td>{{u.active?'Activo':'Desactivado'}}</td><td><button class="secondary compact" @click="edit(u)">Gestionar</button></td></tr></tbody></table></div><Pagination :page="page" :total="data.total" :busy="busy" @change="page=$event" /></section><AppModal v-if="open" :title="reset?'Restablecer contraseña':selected?'Gestionar usuario':'Nuevo usuario'" :busy="saving" @close="open=false"><p v-if="formError" class="notice error" role="alert">{{formError}}</p><form v-if="!reset" class="stack" @submit.prevent="save"><label>Nombre<input v-model="form.name" required maxlength="100" /></label><label>Correo de la cuenta<input v-model="form.email" type="email" required /></label><label>Usuario<input v-model="form.username" required minlength="3" maxlength="40" pattern="[a-zA-Z0-9_.\-]+" :disabled="!!selected" autocapitalize="none" /></label><label>Rol<select v-model="form.role"><option v-for="r in roles" :key="r" :value="r">{{roleLabels[r]}}</option></select></label><label v-if="!selected">Contraseña inicial<input v-model="form.password" type="password" minlength="10" maxlength="128" autocomplete="new-password" required /></label><p v-if="!selected" class="muted small">La persona deberá cambiar esta contraseña en su primer acceso.</p><label v-if="selected" class="check"><input v-model="form.active" type="checkbox" /> Cuenta activa</label><button :disabled="saving">{{saving?'Guardando…':'Guardar usuario'}}</button><button v-if="selected" type="button" class="secondary" @click="reset=true;password=''">Restablecer contraseña</button></form><form v-else class="stack" @submit.prevent="resetPassword"><p>Cuenta: {{selected?.name}}</p><label>Nueva contraseña temporal<input v-model="password" type="password" required minlength="10" maxlength="128" autocomplete="new-password" /></label><p class="muted small">Se cerrarán sus sesiones y deberá cambiarla en su próximo acceso.</p><button :disabled="saving">Guardar contraseña temporal</button><button type="button" class="secondary" @click="reset=false">Volver</button></form></AppModal></template>
